function t(t){if(!t)return"-";let e;if("number"==typeof t||"string"==typeof t&&/^\d+$/.test(t.trim())){const i=Number(t);e=new Date(i>1e12?i:1e3*i)}else e=new Date(t);return e.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}function e(t){if(t<60)return t+"分钟";const e=Math.floor(t/60),i=t%60;return i>0?`${e}h ${i}m`:`${e}h`}function i(t){return t?t>=1e8?(t/1e8).toFixed(2)+"亿":t>=1e4?(t/1e4).toFixed(2)+"万":t.toLocaleString():"0"}export{t as a,e as b,i as f};
